		private void Rap_KartelaPages_Format2_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
System.Data.DataSet ds = ((System.Data.DataSet)this.DataSource);
            if (ds == null || ds.Tables[0].Rows.Count == 0)
            {
                GroupHeader1.Visible = false;
                Detail.Visible = false;
                GroupFooter1.Visible = false;
            }
}

private void PageFooter_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	System.Data.DataSet ds = ((System.Data.DataSet)this.DataSource);
            if (ds == null || ds.Tables[0].Rows.Count == 0)
                GroupFooter1.Visible = false;
}
 public static string ktheMuaj(int index)
        {
            switch (index)
            {
                case 1: return "Janar";
                case 2: return "Shkurt";
                case 3: return "Mars";
                case 4: return "Prill";
                case 5: return "Maj";
                case 6: return "Qershor";
                case 7: return "Korrik";
                case 8: return "Gusht";
                case 9: return "Shtator";
                case 10: return "Tetor";
                case 11: return "Nentor";
                case 12: return "Dhjetor";
                default: return "gabim";
            }

        }
        public static string getMonth(int index)
        {
            switch (index)
            {
                case 1: return "Jannuary";
                case 2: return "February";
                case 3: return "March";
                case 4: return "April";
                case 5: return "May";
                case 6: return "June";
                case 7: return "July";
                case 8: return "August";
                case 9: return "September";
                case 10: return "October";
                case 11: return "November";
                case 12: return "December";
                default: return "gabim";
            }

        }
private void xrLabel42_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
//this.GetCurrentColumnValue("MUAJI").ToString()
if(GetCurrentColumnValue("idgjuha") != null && GetCurrentColumnValue("MUAJI") != null )
	xrLabel42.Text = (Convert.ToInt32(GetCurrentColumnValue("idgjuha").ToString()) == 1)
				? getMonth(Convert.ToInt32(GetCurrentColumnValue("MUAJI").ToString()))
				: ktheMuaj(Convert.ToInt32(GetCurrentColumnValue("MUAJI").ToString()));}



